// TestBuildDeniedPayloadLinux verifies how buildDeniedPayload classifies
// denied_path entries for non-Darwin sandboxes (Linux bubblewrap / bwrap).
//
// Each fixture exercises one filesystem case that previously caused bwrap
// failures or polluted $HOME when passed unconditionally as --tmpfs:
//
//	directories - existing empty and non-empty directories go to Dirs (--tmpfs)
//	non-dirs    - regular files and Unix sockets go to Files (--ro-bind /dev/null),
//	              preventing "Destination is not a directory"
//	symlinks    - symlinks to files or directories (and dangling links) are skipped
//	              to avoid "Can't mount on symlink destination"; normalizePaths
//	              already appends their RealPath targets when they exist
//	missing     - non-existent paths are skipped so bwrap --tmpfs does not
//	              create stray empty directories under $HOME
func TestBuildDeniedPayloadLinux(t *testing.T) {
	dir := t.TempDir()

	// directories: both empty and populated directories map to Dirs (--tmpfs)
	emptyDir := filepath.Join(dir, "empty_dir")
	if err := os.Mkdir(emptyDir, 0o755); err != nil {
		t.Fatalf("mkdir empty_dir: %v", err)
	}

	nonEmptyDir := filepath.Join(dir, "non_empty_dir")
	if err := os.Mkdir(nonEmptyDir, 0o755); err != nil {
		t.Fatalf("mkdir non_empty_dir: %v", err)
	}
	if err := os.WriteFile(filepath.Join(nonEmptyDir, "item"), []byte("x"), 0o600); err != nil {
		t.Fatalf("write item: %v", err)
	}

	// regular file: must be masked with --ro-bind /dev/null via Files
	regFile := filepath.Join(dir, "allow_tool")
	if err := os.WriteFile(regFile, []byte("rule"), 0o600); err != nil {
		t.Fatalf("write allow_tool: %v", err)
	}

	// Unix domain socket: !IsDir() so it routes to Files rather than Dirs
	sockPath := filepath.Join(dir, "daemon.sock")
	ln, err := net.Listen("unix", sockPath)
	if err != nil {
		t.Fatalf("listen unix: %v", err)
	}
	defer ln.Close()

	// symlinks: skipped regardless of target type or dangling state because
	// bwrap refuses symlink mount destinations and RealPath covers valid targets
	linkDir := filepath.Join(dir, "link_dir")
	if err := os.Symlink(emptyDir, linkDir); err != nil {
		t.Fatalf("symlink dir: %v", err)
	}

	linkFile := filepath.Join(dir, "link_file")
	if err := os.Symlink(regFile, linkFile); err != nil {
		t.Fatalf("symlink file: %v", err)
	}

	danglingLink := filepath.Join(dir, "dangling_link")
	if err := os.Symlink(filepath.Join(dir, "missing_target"), danglingLink); err != nil {
		t.Fatalf("symlink dangling: %v", err)
	}

	// missing path: skipped on Linux so bwrap does not create an empty directory
	missingPath := filepath.Join(dir, "does_not_exist")

	got := buildDeniedPayload([]string{
		emptyDir,
		nonEmptyDir,
		regFile,
		sockPath,
		linkDir,
		linkFile,
		danglingLink,
		missingPath,
	}, "linux")

	// only existing real directories should appear in Dirs
	wantDirs := []string{emptyDir, nonEmptyDir}
	if !slices.Equal(got.Dirs, wantDirs) {
		t.Fatalf("Dirs = %v, want %v", got.Dirs, wantDirs)
	}

	// existing non-directory entries (regular files and sockets) belong in Files
	wantFiles := []string{regFile, sockPath}
	if !slices.Equal(got.Files, wantFiles) {
		t.Fatalf("Files = %v, want %v", got.Files, wantFiles)
	}
}

// TestBuildDeniedPayloadDarwin verifies how buildDeniedPayload classifies
// denied_path entries for Darwin (macOS Seatbelt).
//
// Unlike bwrap, Seatbelt evaluates (subpath ...) rules without touching the
// filesystem, so missing paths are preserved in Dirs to block future writes at
// those locations, existing directories go to Dirs, and existing regular files
// go to Files (literal).
func TestBuildDeniedPayloadDarwin(t *testing.T) {
	dir := t.TempDir()

	// existing directory -> Dirs (Seatbelt subpath rule)
	emptyDir := filepath.Join(dir, "empty_dir")
	if err := os.Mkdir(emptyDir, 0o755); err != nil {
		t.Fatalf("mkdir empty_dir: %v", err)
	}

	// existing file -> Files (Seatbelt literal rule)
	regFile := filepath.Join(dir, "auth.json")
	if err := os.WriteFile(regFile, []byte("{}"), 0o600); err != nil {
		t.Fatalf("write auth.json: %v", err)
	}

	// non-existent path -> Dirs on Darwin so future creations remain denied
	missingPath := filepath.Join(dir, "future_path")

	got := buildDeniedPayload([]string{
		emptyDir,
		regFile,
		missingPath,
	}, "darwin")

	wantDirs := []string{emptyDir, missingPath}
	if !slices.Equal(got.Dirs, wantDirs) {
		t.Fatalf("Dirs = %v, want %v", got.Dirs, wantDirs)
	}

	wantFiles := []string{regFile}
	if !slices.Equal(got.Files, wantFiles) {
		t.Fatalf("Files = %v, want %v", got.Files, wantFiles)
	}
}

// TestEmbeddedDeniedPathJSON guards the embedded configs/jsons/denied_path.json
// default list against regressions.
//
// Runtime sockets/PID files (daemon.sock, runtime.uid), script fallback secrets
// (.secrets), and legacy migration files (allow_skill) must stay excluded so
// normal daemon, sandbox, and script_* execution are not blocked, while the
// store and channel credentials remain unreadable.
func TestEmbeddedDeniedPathJSON(t *testing.T) {
	var paths []string
	if err := json.Unmarshal(configs.DeniedPath, &paths); err != nil {
		t.Fatalf("unmarshal configs.DeniedPath: %v", err)
	}

	// entries removed to prevent blocking runtime/sandbox/script fallback flows
	for _, excluded := range []string{
		"~/.config/agenvoy/.secrets",
		"~/.config/agenvoy/daemon.sock",
		"~/.config/agenvoy/runtime.uid",
		"~/.config/agenvoy/allow_skill",
	} {
		if slices.Contains(paths, excluded) {
			t.Fatalf("configs.DeniedPath should not contain %q", excluded)
		}
	}

	// store and channel credential paths must stay unreadable
	for _, required := range []string{
		"~/.config/agenvoy/.store",
		"~/.config/agenvoy/.telegram",
		"~/.config/agenvoy/.discord",
		"~/.config/agenvoy/.line",
	} {
		if !slices.Contains(paths, required) {
			t.Fatalf("configs.DeniedPath should keep %q", required)
		}
	}
}
